$filePath = "X:\code\copilot-worktrees\P08\cirvine-msft-effective-bassoon\assets\stats.txt"
$content = [System.IO.File]::ReadAllText($filePath)
$lines = $content -split "`n"
if ($lines[-1] -eq "") { $lines = $lines[0..($lines.Count - 2)] }

Write-Host "Checking each line for illegal characters:"
for ($i = 0; $i -lt $lines.Count; $i++) {
  $line = $lines[$i]
  $illegal = @()
  for ($c = 0; $c -lt $line.Length; $c++) {
    $ch = $line[$c]
    $ascii = [int][char]$ch
    # Allowed: A-Z(65-90), 0-9(48-57), space(32), +(43), |(124), /(47), \(92), _(95), *(42), .(46), #(35), ((40), )(41), :(58), =(61), -(45)
    $allowed = @(32,43,45,46,47,58,61,92,95,42,35,40,41,124) + (65..90) + (48..57)
    if ($allowed -notcontains $ascii) {
      $illegal += "$ch($ascii)"
    }
  }
  if ($illegal.Count -gt 0) {
    Write-Host "Line $($i+1): ILLEGAL CHARS: $($illegal -join ', ')"
  } else {
    Write-Host "Line $($i+1): OK"
  }
}

